import sys


def classify_root(N, edges, S, T):
    edges = list(edges)
    reverse = [[] for _ in range(N)]
    for u, v, w in edges:
        reverse[v].append(u)

    reaches_t = [False] * N
    reaches_t[T] = True
    stack = [T]
    while stack:
        v = stack.pop()
        for u in reverse[v]:
            if not reaches_t[u]:
                reaches_t[u] = True
                stack.append(u)

    if not reaches_t[S]:
        return ('unreachable', None)

    relevant_edges = [
        (u, v, w) for u, v, w in edges
        if reaches_t[u] and reaches_t[v]
    ]
    K = sum(reaches_t)
    dist = [None] * N
    dist[S] = 0

    for _ in range(K - 1):
        next_dist = dist.copy()
        changed = False
        for u, v, w in relevant_edges:
            if dist[u] is None:
                continue
            candidate = dist[u] + w
            if next_dist[v] is None or candidate < next_dist[v]:
                next_dist[v] = candidate
                changed = True
        dist = next_dist
        if not changed:
            return ('finite', dist[T])

    # Test round K using the unchanged round K-1 distances.
    for u, v, w in relevant_edges:
        if dist[u] is None:
